 case WM_MOUSEMOVE:{float s=GetDpiForWindow(w)/96.f,x=GET_X_LPARAM(lp)/s,y=GET_Y_LPARAM(lp)/s;int h=page!=1&&visual::hit(x,y,primaryRect());if(h!=hover){hover=h;InvalidateRect(w,nullptr,FALSE);}return 0;}
 case WM_LBUTTONUP:{float s=GetDpiForWindow(w)/96.f,x=GET_X_LPARAM(lp)/s,y=GET_Y_LPARAM(lp)/s;
 if(y<55&&x>canvas.width-78){if(page!=1)finish();}else if(y<55&&x>canvas.width-120)ShowWindow(w,SW_MINIMIZE);
 else if(page==0&&visual::hit(x,y,primaryRect()))startInstall();else if(page==0&&y>=350&&y<382)page=3;else if(page==2&&y>=350&&y<387)launch=!launch;else if(page==3){auto g=settingsGeometry();if(visual::hit(x,y,g.browse))browseFolder();else if(visual::hit(x,y,g.back))page=0;else if(visual::hit(x,y,g.ru))setupEnglish=false;else if(visual::hit(x,y,g.en))setupEnglish=true;else if(visual::hit(x,y,g.light))canvas.dark=false;else if(visual::hit(x,y,g.dark))canvas.dark=true;else if(visual::hit(x,y,g.desktopRow))desktopShortcut=!desktopShortcut;else if(visual::hit(x,y,g.menuRow))startMenuShortcut=!startMenuShortcut;else if(visual::hit(x,y,g.accept))startInstall();}else if(page==2&&visual::hit(x,y,primaryRect()))finish();syncPathEdit();InvalidateRect(w,nullptr,FALSE);return 0;}
 case WM_KEYDOWN:if(wp==VK_SPACE&&page==2)launch=!launch;if(wp==VK_RETURN){if(page==0||page==3)startInstall();else if(page==2)finish();}if(wp==VK_ESCAPE&&page!=1)finish();syncPathEdit();InvalidateRect(w,nullptr,FALSE);return 0;
 case WM_TIMER:if(wp==1&&installer){std::ifstream f(progressPath);int value;if(f>>value)progress=std::clamp(value,0,100);}if(wp==99){KillTimer(w,99);const wchar_t* paths[]={L"setup-welcome.png",L"setup-progress.png",L"setup-finish.png",L"setup-settings.png"};if(!visual::productFont.collection||!setupAxisValid){PostQuitMessage(1);return 0;}visual::capture(w,paths[page]);if(++page==4){DestroyWindow(w);return 0;}progress=72;syncPathEdit();SetTimer(w,99,250,nullptr);}if(wp==2){page=2;KillTimer(w,1);KillTimer(w,2);}if(installer&&WaitForSingleObject(installer,0)==WAIT_OBJECT_0){DWORD code;GetExitCodeProcess(installer,&code);CloseHandle(installer);installer=nullptr;std::error_code ec;std::filesystem::remove(temporary,ec);std::filesystem::remove(progressPath,ec);KillTimer(w,1);page=code?0:2;if(!code&&!saveInstallShortcuts())MessageBoxW(w,st(L"Не удалось сохранить ярлыки.",L"Could not save shortcuts.").c_str(),L"Torrent",MB_ICONWARNING);if(!code&&!saveInstallTheme())MessageBoxW(w,st(L"Приложение установлено, но сохранить тему не удалось.",L"Installed, but could not save the selected theme.").c_str(),L"Torrent",MB_ICONWARNING);if(code)MessageBoxW(w,L"Установка не завершена. Попробуйте снова.",L"Torrent",MB_ICONERROR);}InvalidateRect(w,nullptr,FALSE);return 0;
